    {"t": 8.0, "event": "Кассир касается сумки, начинает её осматривать."},
    {"t": 9.5, "event": "Инкассатор отходит от стола и поворачивается к двери."},
    {"t": 11.5, "event": "Инкассатор выходит из помещения, кассир продолжает осматривать сумку на столе."}
  ],
  "object_states": [
    {"object": "ноутбук", "t": 0.0, "state": "открыт, на столе"},
    {"object": "зелёная сумка", "t": 4.5, "state": "в руках у инкассатора"},
    {"object": "зелёная сумка", "t": 7.0, "state": "на столе, кассир её рассматривает"},
    {"object": "дверь кассы", "t": 2.0, "state": "открыта, входит инкассатор"},
    {"object": "дверь кассы", "t": 11.5, "state": "открыта, инкассатор выходит"}
